"""Download / locate the GunPointOldVersusYoung UCR dataset (.ts files).

Order of resolution:
1. Existing workspace data/GunPointOldVersusYoung/*.ts
2. REPRO_DATA_CACHE/uea_ucr/*.ts  (shared cache)
3. REPRO_DATA_CACHE direct copy (zip already present)
4. Download zip from timeseriesclassification.com (paper's host) -> cache + workspace
"""

import io
import os
import zipfile
from pathlib import Path

import requests

from src import config


def _cache_dirs():
    cache = os.environ.get(config.CACHE_ENV)
    if not cache:
        return []
    c = Path(cache)
    return [c / "uea_ucr", c]


def data_dir() -> Path:
    return config.ROOT / config.DATA_DIRNAME


def _ts_paths_in(d: Path):
    return {
        "TRAIN": d / f"{config.DATASET}_TRAIN.ts",
        "TEST": d / f"{config.DATASET}_TEST.ts",
    }


def find_existing():
    for d in [data_dir()] + _cache_dirs():
        if d.is_dir():
            paths = _ts_paths_in(d)
            if all(p.exists() for p in paths.values()):
                return d, paths
    return None, None


def download():
    """Download the .zip from timeseriesclassification.com and extract both .ts files."""
    dest_cache = _cache_dirs()
    target = data_dir()
    target.mkdir(parents=True, exist_ok=True)
    resp = requests.get(config.DATASET_ZIP_URL, timeout=config.DOWNLOAD_TIMEOUT_SECONDS)
    resp.raise_for_status()
    with zipfile.ZipFile(io.BytesIO(resp.content)) as zf:
        for name in zf.namelist():
            if name.endswith(("_TRAIN.ts", "_TEST.ts")):
                data = zf.read(name)
                out = target / Path(name).name
                out.write_bytes(data)
                # also seed the cache so future runs do not re-download
                for cd in dest_cache:
                    try:
                        cd.mkdir(parents=True, exist_ok=True)
                        (cd / Path(name).name).write_bytes(data)
                    except OSError:
                        pass
    paths = _ts_paths_in(target)
    for p in paths.values():
        if not p.exists():
            raise FileNotFoundError(f"Expected {p} after extraction")
    return target, paths


def ensure_data():
    d, paths = find_existing()
    if d is not None:
        print(f"[download] using existing data at {d}")
        return paths
    print(f"[download] downloading {config.DATASET} from {config.DATASET_ZIP_URL}")
    d, paths = download()
    print(f"[download] extracted to {d}")
    return paths


if __name__ == "__main__":
    ensure_data()

"""Parser for UEA/UCR .ts files -> X (n_cases, series_length), y (labels).

Handles the standard formats: label-first `classLabel,value,...` and
label-last `value,...,classLabel`. No normalization is applied (R2).
"""

import re
from pathlib import Path

import numpy as np


def _parse_tag(tag, line):
    parts = line.strip().split(" ", 1)
    if len(parts) == 1:
        return ""
    return parts[1].strip()


def load_ts(path):
    path = Path(path)
    equal_length = None
    series_length = None
    label_last = None
    class_labels = None
    data = []
    in_data = False
    with open(path, encoding="utf-8", errors="replace") as f:
        for raw in f:
            line = raw.strip()
            if not line:
                continue
            if in_data:
                data.append(line)
                continue
            low = line.lower()
            if low.startswith("@equalLength".lower()):
                equal_length = _parse_tag("@equalLength", line).lower() == "true"
            elif low.startswith("@seriesLength".lower()):
                series_length = int(_parse_tag("@seriesLength", line))
            elif low.startswith("@classLabel".lower()):
                parts = line.split()
                label_last = parts[1].strip().lower() == "true"
                class_labels = parts[2:] if len(parts) > 2 else None
            elif low.startswith("@data"):
                in_data = True

    rows, labels = [], []
    for line in data:
        parts = [p for p in re.split(r"[,:]", line) if p.strip() != ""]
        if label_last:
            value_part, label_part = parts[:-1], parts[-1]
        else:
            label_part, value_part = parts[0], parts[1:]
        rows.append([float(v) for v in value_part])
        labels.append(label_part)

    X = np.asarray(rows, dtype=float)
    y = np.asarray(labels)
    if equal_length is not None and not equal_length:
        raise ValueError(f"{path} is not equal length; unsupported here")
    if series_length is not None and X.shape[1] != series_length:
        raise ValueError(f"{path}: series length {X.shape[1]} != declared {series_length}")
    if class_labels is not None:
        unknown = set(np.unique(y)) - set(class_labels)
        if unknown:
            raise ValueError(f"{path}: labels not in declared class labels: {unknown}")
    return X, y

"""Audit helper: read the authors' stored result CSV for the target dataset.

The authors' repo ships classification-models/results/<problem>.csv only after
their R pipeline has been run; the data/ folder and those CSVs are not pushed
to git. This function is an audit only and never supplies the reported number.
"""

from pathlib import Path

import pandas as pd

from src import config


def find_authors_result():
    repo = config.ROOT / "repo"
    candidates = list(repo.glob(f"**/results/{config.DATASET}.csv"))
    for c in candidates:
        try:
            df = pd.read_csv(c)
        except Exception:
            continue
        # look for a moments / FTM feature-set row
        fs_col = next((col for col in df.columns if col.lower() == "feature_set"), None)
        if fs_col is None:
            return {"path": str(c), "columns": list(df.columns), "note": "no feature_set column"}
        rows = df[df[fs_col].astype(str).str.contains("1,2|FTM|Moment", case=False, regex=True)]
        acc_col = next((col for col in df.columns if "acc" in col.lower()), None)
        if acc_col and len(rows):
            return {
                "path": str(c),
                "feature_sets": sorted(rows[fs_col].astype(str).unique().tolist()),
                "mean_accuracy_percent": float(rows[acc_col].mean() * 100.0),
                "n_rows": int(len(rows)),
            }
        return {"path": str(c), "columns": list(df.columns)}
    return {"path": None, "note": "authors' results CSV not present in repo snapshot (data/results not pushed)"}


if __name__ == "__main__":
    print(find_authors_result())
